public static void check(Solution solution) {
    assert Arrays.equals(solution.findClosestElements(new int[]{1,3,5,7,9}, 4, 6), new int[]{3, 5, 7, 9});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,3,5,7,9}, 2, 6), new int[]{5, 7});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,3,5,7,9}, 1, 6), new int[]{5});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,3,5,7,9}, 5, 6), new int[]{1, 3, 5, 7, 9});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,2,3,4,5}, 2, 3), new int[]{2, 3});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,1,1,1,1}, 3, 1), new int[]{1, 1, 1});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,3,5,7,9}, 5, 8), new int[]{1, 3, 5, 7, 9});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,2,3,4,5}, 4, 3), new int[]{1, 2, 3, 4});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,2,2,2,3,3,4,5}, 4, 2), new int[]{1, 2, 2, 2});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,1,2,3,4,5}, 4, -1), new int[]{1, 1, 2, 3});
    assert Arrays.equals(solution.findClosestElements(new int[]{1,2,3,4,5}, 1, 2), new int[]{2});
